const BUMPP_OLD: string = "import type { Manifest } from './manifest'\nimport type { Operation } from './operation'\nimport type { NpmScript } from './types/version-bump-progress'\nimport { x } from 'tinyexec'\nimport { readJsoncFile } from './fs'\nimport { isManifest } from './manifest'\nimport { ProgressEvent } from './types/version-bump-progress'\n\n/**\n * Runs the specified NPM script in the package.json file.\n */\nexport async function runNpmScript(script: NpmScript, operation: Operation): Promise<Operation> {\n  const { cwd, ignoreScripts } = operation.options\n\n  if (!ignoreScripts) {\n    const { data: manifest } = await readJsoncFile('package.json', cwd)\n\n    if (isManifest(manifest) && hasScript(manifest, script)) {\n      await x('npm', ['run', script, '--silent'], {\n        throwOnError: true,\n        nodeOptions: { stdio: 'inherit' },\n      })\n      operation.update({ event: ProgressEvent.NpmScript, script })\n    }\n  }\n\n  return operation\n}\n\n/**\n * Determines whether the specified NPM script exists in the given manifest.\n */\nfunction hasScript(manifest: Manifest, script: NpmScript): boolean {\n  const scripts = manifest.scripts as Record<NpmScript, string> | undefined\n\n  if (scripts && typeof scripts === 'object')\n    return Boolean(scripts[script])\n\n  return false\n}\n";
const BUMPP_NEW: string = "import type { Manifest } from './manifest'\nimport type { Operation } from './operation'\nimport type { NpmScript } from './types/version-bump-progress'\nimport { existsSync } from 'node:fs'\nimport path from 'node:path'\nimport { x } from 'tinyexec'\nimport { readJsoncFile } from './fs'\nimport { isManifest } from './manifest'\nimport { ProgressEvent } from './types/version-bump-progress'\n\n/**\n * Runs the specified NPM script in the package.json file.\n */\nexport async function runNpmScript(script: NpmScript, operation: Operation): Promise<Operation> {\n  const { cwd, ignoreScripts } = operation.options\n\n  if (!ignoreScripts && existsSync(path.join(cwd, 'package.json'))) {\n    const { data: manifest } = await readJsoncFile('package.json', cwd)\n\n    if (isManifest(manifest) && hasScript(manifest, script)) {\n      await x('npm', ['run', script, '--silent'], {\n        throwOnError: true,\n        nodeOptions: { stdio: 'inherit' },\n      })\n      operation.update({ event: ProgressEvent.NpmScript, script })\n    }\n  }\n\n  return operation\n}\n\n/**\n * Determines whether the specified NPM script exists in the given manifest.\n */\nfunction hasScript(manifest: Manifest, script: NpmScript): boolean {\n  const scripts = manifest.scripts as Record<NpmScript, string> | undefined\n\n  if (scripts && typeof scripts === 'object')\n    return Boolean(scripts[script])\n\n  return false\n}\n";

export function isolateSubscriptionObserverReads(source: string): string | null {
  if (!source.includes("export function createAtom")) return null;
  return source === STORE_OLD ? STORE_NEW : null;
}

export function brandNativeRequestInstance(source: string): string | null {
  if (!source.includes("export class Request")) return null;
  return source === REQUEST_OLD ? REQUEST_NEW : null;
}

export function skipScriptsWithoutPackageJson(source: string): string | null {
  if (!source.includes("export async function runNpmScript")) return null;
  return source === BUMPP_OLD ? BUMPP_NEW : null;
}

export interface Batch30Input {
  root: string;
  output: string;
  sourcePattern?: string;
  nodePath?: string | null;
  nodeModules?: string | null;
  testCommand: readonly string[];
  bwrap?: string;
}

function readLocal(dir: string, path: string): string | null {
  try {
    return readFileSync(join(dir, path), "utf8");
  } catch {
    return null;
  }
}

function filesOf(dir: string, pattern: string | undefined): string[] {
  const listed = practiceGit(dir, ["ls-files"]);
  if (!listed.ok) return [];
  return listed.out.split("\n").map((p) => p.trim()).filter((p) => /\.(?:tsx?|js)$/.test(p) && !p.endsWith(".d.ts") && (!pattern || new RegExp(pattern).test(p)));
}

/** Apply the one repair the failure can prove, then require the published test to pass in the sandbox. */
export function repairBatch30(input: Batch30Input): { diff: string; file: string } | null {
  if (!/Error|not equal|Expected|Invalid|fail|toEqual|toBe|toBeInstanceOf|AssertionError|TypeError|hasInstance|ENOENT|package\.json|resolves|activeSub/i.test(input.output)) return null;
  const edits: { path: string; next: string; original: string }[] = [];
  for (const path of filesOf(input.root, input.sourcePattern)) {
    const original = readLocal(input.root, path);
    if (original === null) continue;
    const next = isolateSubscriptionObserverReads(original) ?? brandNativeRequestInstance(original) ?? skipScriptsWithoutPackageJson(original);
    if (next && next !== original) edits.push({ path, next, original });
  }
  if (edits.length !== 1) return null;
  const edit = edits[0]!;
  try {
    writeFileSync(join(input.root, edit.path), edit.next);
    const again = runInPracticeSandbox(input.root, input.testCommand, 180_000, {
      capture: true, nodePath: input.nodePath, nodeModules: input.nodeModules, ...(input.bwrap ? { bwrap: input.bwrap } : {}),
    });
    if (again.unsafe || again.code !== 0) return null;
    const diff = practiceGit(input.root, ["diff", "--no-color", "--no-ext-diff", "--no-renames", "--", edit.path]);
    if (!diff.ok || !diff.out.trim()) return null;
    return { diff: diff.out, file: edit.path };
  } finally {
    writeFileSync(join(input.root, edit.path), edit.original);
  }
}
